--
-- Table structure for table `autorizacao_acesso`
--

DROP TABLE IF EXISTS `autorizacao_acesso`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `autorizacao_acesso` (
  `id_autorizacao` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_visitante` bigint(20) unsigned NOT NULL,
  `id_unidade` bigint(20) unsigned NOT NULL,
  `id_responsavel` bigint(20) unsigned NOT NULL,
  `inicio_validade` datetime NOT NULL,
  `fim_validade` datetime NOT NULL,
  `recorrente` tinyint(1) NOT NULL DEFAULT 0,
  `motivo` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVA',
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_autorizacao`),
  KEY `fk_autorizacao_responsavel` (`id_responsavel`),
  KEY `idx_autorizacao_unidade_periodo` (`id_unidade`,`status`,`inicio_validade`,`fim_validade`),
  KEY `idx_autorizacao_visitante` (`id_visitante`,`status`),
  CONSTRAINT `fk_autorizacao_responsavel` FOREIGN KEY (`id_responsavel`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_autorizacao_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `fk_autorizacao_visitante` FOREIGN KEY (`id_visitante`) REFERENCES `visitante` (`id_visitante`) ON UPDATE CASCADE,
  CONSTRAINT `chk_autorizacao_periodo` CHECK (`fim_validade` > `inicio_validade`),
  CONSTRAINT `chk_autorizacao_status` CHECK (`status` in ('ATIVA','SUSPENSA','CANCELADA'))
) ENGINE=InnoDB AUTO_INCREMENT=6001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

