DROP TABLE IF EXISTS `autorizacao_recorrencia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `autorizacao_recorrencia` (
  `id_recorrencia` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_autorizacao` bigint(20) unsigned NOT NULL,
  `dia_semana` tinyint(3) unsigned NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fim` time NOT NULL,
  PRIMARY KEY (`id_recorrencia`),
  UNIQUE KEY `uq_ar_regra` (`id_autorizacao`,`dia_semana`,`hora_inicio`,`hora_fim`),
  CONSTRAINT `fk_ar_autorizacao` FOREIGN KEY (`id_autorizacao`) REFERENCES `autorizacao_acesso` (`id_autorizacao`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_ar_dia` CHECK (`dia_semana` between 1 and 7),
  CONSTRAINT `chk_ar_horario` CHECK (`hora_fim` > `hora_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=601 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

