DROP TABLE IF EXISTS `chamado`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chamado` (
  `id_chamado` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_unidade` bigint(20) unsigned DEFAULT NULL,
  `id_categoria_chamado` bigint(20) unsigned NOT NULL,
  `id_solicitante` bigint(20) unsigned NOT NULL,
  `assunto` varchar(200) NOT NULL,
  `prioridade` varchar(20) NOT NULL DEFAULT 'NORMAL',
  `status` varchar(30) NOT NULL DEFAULT 'ABERTO',
  `data_abertura` datetime NOT NULL DEFAULT current_timestamp(),
  `data_encerramento` datetime DEFAULT NULL,
  PRIMARY KEY (`id_chamado`),
  KEY `fk_chamado_solicitante` (`id_solicitante`),
  KEY `idx_chamado_condominio_status` (`id_condominio`,`status`,`data_abertura`),
  KEY `idx_chamado_unidade` (`id_unidade`,`status`),
  KEY `idx_chamado_categoria` (`id_categoria_chamado`,`status`),
  CONSTRAINT `fk_chamado_categoria` FOREIGN KEY (`id_categoria_chamado`) REFERENCES `categoria_chamado` (`id_categoria_chamado`) ON UPDATE CASCADE,
  CONSTRAINT `fk_chamado_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_chamado_solicitante` FOREIGN KEY (`id_solicitante`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_chamado_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `chk_chamado_prioridade` CHECK (`prioridade` in ('BAIXA','NORMAL','ALTA','URGENTE')),
  CONSTRAINT `chk_chamado_status` CHECK (`status` in ('ABERTO','EM_ATENDIMENTO','AGUARDANDO','RESOLVIDO','ENCERRADO','CANCELADO')),
  CONSTRAINT `chk_chamado_encerramento` CHECK (`data_encerramento` is null or `data_encerramento` >= `data_abertura`)
) ENGINE=InnoDB AUTO_INCREMENT=3001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
