--
-- Table structure for table `chamado_atribuicao`
--

DROP TABLE IF EXISTS `chamado_atribuicao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chamado_atribuicao` (
  `id_atribuicao` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_chamado` bigint(20) unsigned NOT NULL,
  `id_funcionario_condominio` bigint(20) unsigned DEFAULT NULL,
  `id_setor` bigint(20) unsigned DEFAULT NULL,
  `id_fornecedor` bigint(20) unsigned DEFAULT NULL,
  `atribuido_por` bigint(20) unsigned DEFAULT NULL,
  `data_inicio` datetime NOT NULL DEFAULT current_timestamp(),
  `data_fim` datetime DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_atribuicao`),
  KEY `fk_ca_funcionario` (`id_funcionario_condominio`),
  KEY `fk_ca_setor` (`id_setor`),
  KEY `fk_ca_fornecedor` (`id_fornecedor`),
  KEY `fk_ca_usuario` (`atribuido_por`),
  KEY `idx_chamado_atribuicao` (`id_chamado`,`ativo`,`data_inicio`),
  CONSTRAINT `fk_ca_chamado` FOREIGN KEY (`id_chamado`) REFERENCES `chamado` (`id_chamado`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ca_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ca_funcionario` FOREIGN KEY (`id_funcionario_condominio`) REFERENCES `funcionario_condominio` (`id_vinculo_funcionario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ca_setor` FOREIGN KEY (`id_setor`) REFERENCES `setor_condominio` (`id_setor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ca_usuario` FOREIGN KEY (`atribuido_por`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_ca_responsavel` CHECK ((`id_funcionario_condominio` is not null) + (`id_setor` is not null) + (`id_fornecedor` is not null) = 1),
  CONSTRAINT `chk_ca_periodo` CHECK (`data_fim` is null or `data_fim` >= `data_inicio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

