  `id_unidade` bigint(20) unsigned NOT NULL,
  `tipo_cobranca` varchar(30) NOT NULL,
  `data_geracao` datetime NOT NULL DEFAULT current_timestamp(),
  `observacao` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_cobranca`),
  UNIQUE KEY `uq_cobranca_conta_receber` (`id_conta_receber`),
  KEY `idx_cobranca_unidade` (`id_unidade`),
  CONSTRAINT `fk_cobranca_conta_receber` FOREIGN KEY (`id_conta_receber`) REFERENCES `conta_receber` (`id_conta_receber`) ON UPDATE CASCADE,
  CONSTRAINT `fk_cobranca_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `chk_cobranca_tipo` CHECK (`tipo_cobranca` in ('CONDOMINIAL','EXTRAORDINARIA','MULTA','RESERVA','ACORDO','OUTRA'))
) ENGINE=InnoDB AUTO_INCREMENT=3056 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
