--
-- Table structure for table `conta_receber`
--

DROP TABLE IF EXISTS `conta_receber`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `conta_receber` (
  `id_conta_receber` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_categoria_financeira` bigint(20) unsigned NOT NULL,
  `id_centro_custo` bigint(20) unsigned DEFAULT NULL,
  `id_conta_bancaria` bigint(20) unsigned DEFAULT NULL,
  `descricao` varchar(255) NOT NULL,
  `competencia` date NOT NULL,
  `data_emissao` date DEFAULT NULL,
  `data_vencimento` date NOT NULL,
  `valor` decimal(14,2) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ABERTA',
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_conta_receber`),
  KEY `fk_cr_categoria` (`id_categoria_financeira`),
  KEY `fk_cr_centro` (`id_centro_custo`),
  KEY `fk_cr_conta_bancaria` (`id_conta_bancaria`),
  KEY `idx_conta_receber_vencimento_status` (`id_condominio`,`status`,`data_vencimento`),
  CONSTRAINT `fk_cr_categoria` FOREIGN KEY (`id_categoria_financeira`) REFERENCES `categoria_financeira` (`id_categoria_financeira`) ON UPDATE CASCADE,
  CONSTRAINT `fk_cr_centro` FOREIGN KEY (`id_centro_custo`) REFERENCES `centro_custo` (`id_centro_custo`) ON UPDATE CASCADE,
  CONSTRAINT `fk_cr_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_cr_conta_bancaria` FOREIGN KEY (`id_conta_bancaria`) REFERENCES `conta_bancaria` (`id_conta_bancaria`) ON UPDATE CASCADE,
  CONSTRAINT `chk_cr_valor` CHECK (`valor` > 0),
  CONSTRAINT `chk_cr_status` CHECK (`status` in ('ABERTA','PARCIAL','LIQUIDADA','VENCIDA','CANCELADA'))
) ENGINE=InnoDB AUTO_INCREMENT=3056 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

