DROP TABLE IF EXISTS `contato`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contato` (
  `id_contato` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_pessoa` bigint(20) unsigned NOT NULL,
  `tipo` varchar(20) NOT NULL,
  `valor` varchar(150) NOT NULL,
  `principal` tinyint(1) NOT NULL DEFAULT 0,
  `emergencia` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id_contato`),
  KEY `fk_contato_pessoa` (`id_pessoa`),
  CONSTRAINT `fk_contato_pessoa` FOREIGN KEY (`id_pessoa`) REFERENCES `pessoa` (`id_pessoa`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_contato_tipo` CHECK (`tipo` in ('EMAIL','TELEFONE','CELULAR','OUTRO'))
) ENGINE=InnoDB AUTO_INCREMENT=9192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
