--
-- Table structure for table `contrato`
--

DROP TABLE IF EXISTS `contrato`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contrato` (
  `id_contrato` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_fornecedor` bigint(20) unsigned NOT NULL,
  `id_responsavel` bigint(20) unsigned DEFAULT NULL,
  `objeto` varchar(500) NOT NULL,
  `valor` decimal(14,2) DEFAULT NULL,
  `data_inicio` date NOT NULL,
  `data_fim` date NOT NULL,
  `periodicidade` varchar(50) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVO',
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_contrato`),
  KEY `fk_contrato_fornecedor` (`id_fornecedor`),
  KEY `fk_contrato_responsavel` (`id_responsavel`),
  KEY `idx_contrato_vencimento_status` (`id_condominio`,`status`,`data_fim`),
  CONSTRAINT `fk_contrato_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_contrato_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_contrato_responsavel` FOREIGN KEY (`id_responsavel`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_contrato_valor` CHECK (`valor` is null or `valor` >= 0),
  CONSTRAINT `chk_contrato_datas` CHECK (`data_fim` >= `data_inicio`),
  CONSTRAINT `chk_contrato_status` CHECK (`status` in ('ATIVO','ENCERRADO','CANCELADO','SUSPENSO'))
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

