DROP TABLE IF EXISTS `despesa_recorrente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `despesa_recorrente` (
  `id_despesa_recorrente` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_fornecedor` bigint(20) unsigned DEFAULT NULL,
  `id_categoria_financeira` bigint(20) unsigned NOT NULL,
  `id_centro_custo` bigint(20) unsigned DEFAULT NULL,
  `id_conta_bancaria` bigint(20) unsigned DEFAULT NULL,
  `descricao` varchar(255) NOT NULL,
  `valor` decimal(14,2) NOT NULL,
  `periodicidade` varchar(20) NOT NULL,
  `proxima_geracao` date NOT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_despesa_recorrente`),
  KEY `fk_dr_condominio` (`id_condominio`),
  KEY `fk_dr_fornecedor` (`id_fornecedor`),
  KEY `fk_dr_categoria` (`id_categoria_financeira`),
  KEY `fk_dr_centro` (`id_centro_custo`),
  KEY `fk_dr_conta` (`id_conta_bancaria`),
  CONSTRAINT `fk_dr_categoria` FOREIGN KEY (`id_categoria_financeira`) REFERENCES `categoria_financeira` (`id_categoria_financeira`) ON UPDATE CASCADE,
  CONSTRAINT `fk_dr_centro` FOREIGN KEY (`id_centro_custo`) REFERENCES `centro_custo` (`id_centro_custo`) ON UPDATE CASCADE,
  CONSTRAINT `fk_dr_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_dr_conta` FOREIGN KEY (`id_conta_bancaria`) REFERENCES `conta_bancaria` (`id_conta_bancaria`) ON UPDATE CASCADE,
  CONSTRAINT `fk_dr_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `chk_dr_valor` CHECK (`valor` > 0),
  CONSTRAINT `chk_dr_periodicidade` CHECK (`periodicidade` in ('MENSAL','BIMESTRAL','TRIMESTRAL','SEMESTRAL','ANUAL'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
