--
-- Table structure for table `encomenda`
--

DROP TABLE IF EXISTS `encomenda`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `encomenda` (
  `id_encomenda` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_unidade` bigint(20) unsigned NOT NULL,
  `id_usuario_recebimento` bigint(20) unsigned NOT NULL,
  `id_pessoa_retirante` bigint(20) unsigned DEFAULT NULL,
  `id_usuario_entrega` bigint(20) unsigned DEFAULT NULL,
  `tipo` varchar(30) NOT NULL DEFAULT 'ENCOMENDA',
  `remetente_transportadora` varchar(150) DEFAULT NULL,
  `codigo_rastreio` varchar(100) DEFAULT NULL,
  `data_recebimento` datetime NOT NULL DEFAULT current_timestamp(),
  `data_retirada` datetime DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'RECEBIDA',
  `observacao` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_encomenda`),
  KEY `fk_encomenda_recebimento` (`id_usuario_recebimento`),
  KEY `fk_encomenda_retirante` (`id_pessoa_retirante`),
  KEY `fk_encomenda_entrega` (`id_usuario_entrega`),
  KEY `idx_encomenda_unidade_status` (`id_unidade`,`status`,`data_recebimento`),
  KEY `idx_encomenda_rastreio` (`codigo_rastreio`),
  CONSTRAINT `fk_encomenda_entrega` FOREIGN KEY (`id_usuario_entrega`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_encomenda_recebimento` FOREIGN KEY (`id_usuario_recebimento`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_encomenda_retirante` FOREIGN KEY (`id_pessoa_retirante`) REFERENCES `pessoa` (`id_pessoa`) ON UPDATE CASCADE,
  CONSTRAINT `fk_encomenda_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `chk_encomenda_tipo` CHECK (`tipo` in ('ENCOMENDA','CORRESPONDENCIA','DOCUMENTO','OUTRO')),
  CONSTRAINT `chk_encomenda_status` CHECK (`status` in ('RECEBIDA','NOTIFICADA','RETIRADA','DEVOLVIDA')),
  CONSTRAINT `chk_encomenda_retirada` CHECK (`data_retirada` is null or `data_retirada` >= `data_recebimento`)
) ENGINE=InnoDB AUTO_INCREMENT=2501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
