  `id_usuario` bigint(20) unsigned DEFAULT NULL,
  `data_estorno` datetime NOT NULL DEFAULT current_timestamp(),
  `valor` decimal(14,2) NOT NULL,
  `motivo` varchar(255) NOT NULL,
  PRIMARY KEY (`id_estorno`),
  KEY `fk_estorno_pagamento` (`id_pagamento`),
  KEY `fk_estorno_usuario` (`id_usuario`),
  CONSTRAINT `fk_estorno_pagamento` FOREIGN KEY (`id_pagamento`) REFERENCES `pagamento` (`id_pagamento`) ON UPDATE CASCADE,
  CONSTRAINT `fk_estorno_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_estorno_valor` CHECK (`valor` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
