--
-- Table structure for table `leitura_medidor`
--

DROP TABLE IF EXISTS `leitura_medidor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `leitura_medidor` (
  `id_leitura` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_medidor` bigint(20) unsigned NOT NULL,
  `id_lote` bigint(20) unsigned DEFAULT NULL,
  `id_usuario_registro` bigint(20) unsigned DEFAULT NULL,
  `periodo_inicio` date NOT NULL,
  `periodo_fim` date NOT NULL,
  `leitura_anterior` decimal(14,3) DEFAULT NULL,
  `leitura_atual` decimal(14,3) NOT NULL,
  `consumo` decimal(14,3) DEFAULT NULL,
  `origem` varchar(20) NOT NULL DEFAULT 'MANUAL',
  `data_registro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_leitura`),
  UNIQUE KEY `uq_leitura_medidor_periodo` (`id_medidor`,`periodo_inicio`,`periodo_fim`),
  KEY `fk_leitura_usuario` (`id_usuario_registro`),
  KEY `idx_leitura_medidor_data` (`id_medidor`,`periodo_fim`),
  KEY `idx_leitura_lote` (`id_lote`),
  CONSTRAINT `fk_leitura_lote` FOREIGN KEY (`id_lote`) REFERENCES `lote_importacao_leitura` (`id_lote`) ON UPDATE CASCADE,
  CONSTRAINT `fk_leitura_medidor` FOREIGN KEY (`id_medidor`) REFERENCES `medidor` (`id_medidor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_leitura_usuario` FOREIGN KEY (`id_usuario_registro`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_leitura_periodo` CHECK (`periodo_fim` >= `periodo_inicio`),
  CONSTRAINT `chk_leitura_anterior` CHECK (`leitura_anterior` is null or `leitura_anterior` >= 0),
  CONSTRAINT `chk_leitura_atual` CHECK (`leitura_atual` >= 0),
  CONSTRAINT `chk_leitura_consumo` CHECK (`consumo` is null or `consumo` >= 0),
  CONSTRAINT `chk_leitura_origem` CHECK (`origem` in ('MANUAL','IMPORTACAO','INTEGRACAO'))
) ENGINE=InnoDB AUTO_INCREMENT=4201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
