/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_leitura_bi_consumo

BEFORE INSERT
ON leitura_medidor

FOR EACH ROW

BEGIN

    DECLARE v_metodo
            VARCHAR(20);

    DECLARE v_leitura_anterior
            DECIMAL(14,3);


    SELECT metodo_calculo

    INTO v_metodo

    FROM medidor

    WHERE id_medidor =
          NEW.id_medidor;


    -- ========================================================
    -- Método por diferença
    -- ========================================================

    IF v_metodo = 'DIFERENCA' THEN


        -- Se leitura anterior não foi informada,
        -- procura a última leitura do medidor.

        IF NEW.leitura_anterior IS NULL THEN


            SET v_leitura_anterior =
            (
                SELECT lm.leitura_atual

                FROM leitura_medidor lm

                WHERE
                    lm.id_medidor =
                    NEW.id_medidor

                ORDER BY
                    lm.periodo_fim DESC,
                    lm.id_leitura DESC

                LIMIT 1
            );


            SET NEW.leitura_anterior =
                v_leitura_anterior;

        END IF;


        -- Primeira leitura:
        -- precisa informar leitura anterior.

        IF NEW.leitura_anterior IS NULL THEN

            SIGNAL SQLSTATE '45000'

            SET MESSAGE_TEXT =
            'Informe a leitura anterior para a primeira medição deste medidor.';

        END IF;


        IF
            NEW.leitura_atual
            <
            NEW.leitura_anterior
        THEN

            SIGNAL SQLSTATE '45000'

            SET MESSAGE_TEXT =
            'A leitura atual não pode ser menor que a leitura anterior.';

        END IF;


        SET NEW.consumo =
            NEW.leitura_atual
            -
            NEW.leitura_anterior;


    -- ========================================================
    -- Método informado
    -- ========================================================

    ELSEIF v_metodo = 'INFORMADO' THEN


        IF NEW.consumo IS NULL THEN

            SIGNAL SQLSTATE '45000'

            SET MESSAGE_TEXT =
            'O consumo deve ser informado para este medidor.';

        END IF;


    END IF;

END */;;
DELIMITER ;
