--
-- Table structure for table `lote_importacao_leitura`
--

DROP TABLE IF EXISTS `lote_importacao_leitura`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lote_importacao_leitura` (
  `id_lote` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_usuario` bigint(20) unsigned NOT NULL,
  `nome_arquivo` varchar(255) NOT NULL,
  `origem` varchar(100) DEFAULT NULL,
  `total_registros` int(10) unsigned NOT NULL DEFAULT 0,
  `registros_validos` int(10) unsigned NOT NULL DEFAULT 0,
  `registros_invalidos` int(10) unsigned NOT NULL DEFAULT 0,
  `status` varchar(30) NOT NULL DEFAULT 'PENDENTE',
  `data_importacao` datetime NOT NULL DEFAULT current_timestamp(),
