--
-- Table structure for table `movimentacao_bancaria`
--

DROP TABLE IF EXISTS `movimentacao_bancaria`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movimentacao_bancaria` (
  `id_movimentacao` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_conta_bancaria` bigint(20) unsigned NOT NULL,
  `data_movimentacao` datetime NOT NULL,
  `tipo_movimentacao` varchar(10) NOT NULL,
  `valor` decimal(14,2) NOT NULL,
  `descricao` varchar(255) DEFAULT NULL,
  `identificador_externo` varchar(150) DEFAULT NULL,
  `origem_importacao` varchar(100) DEFAULT NULL,
  `data_importacao` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_movimentacao`),
  KEY `idx_movimentacao_conta_data` (`id_conta_bancaria`,`data_movimentacao`),
  CONSTRAINT `fk_mb_conta` FOREIGN KEY (`id_conta_bancaria`) REFERENCES `conta_bancaria` (`id_conta_bancaria`) ON UPDATE CASCADE,
  CONSTRAINT `chk_mb_tipo` CHECK (`tipo_movimentacao` in ('CREDITO','DEBITO')),
  CONSTRAINT `chk_mb_valor` CHECK (`valor` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=2496 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

