--
-- Table structure for table `ocorrencia`
--

DROP TABLE IF EXISTS `ocorrencia`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ocorrencia` (
  `id_ocorrencia` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_categoria_ocorrencia` bigint(20) unsigned NOT NULL,
  `id_unidade` bigint(20) unsigned DEFAULT NULL,
  `id_area` bigint(20) unsigned DEFAULT NULL,
  `id_responsavel` bigint(20) unsigned DEFAULT NULL,
  `id_usuario_registro` bigint(20) unsigned NOT NULL,
  `titulo` varchar(200) NOT NULL,
  `data_ocorrencia` datetime NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'ABERTA',
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  `data_encerramento` datetime DEFAULT NULL,
  PRIMARY KEY (`id_ocorrencia`),
  KEY `fk_ocorrencia_categoria` (`id_categoria_ocorrencia`),
  KEY `fk_ocorrencia_area` (`id_area`),
  KEY `fk_ocorrencia_responsavel` (`id_responsavel`),
  KEY `fk_ocorrencia_usuario_registro` (`id_usuario_registro`),
  KEY `idx_ocorrencia_condominio` (`id_condominio`,`status`,`data_ocorrencia`),
  KEY `idx_ocorrencia_unidade` (`id_unidade`,`data_ocorrencia`),
  CONSTRAINT `fk_ocorrencia_area` FOREIGN KEY (`id_area`) REFERENCES `area_comum` (`id_area`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ocorrencia_categoria` FOREIGN KEY (`id_categoria_ocorrencia`) REFERENCES `categoria_ocorrencia` (`id_categoria_ocorrencia`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ocorrencia_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ocorrencia_responsavel` FOREIGN KEY (`id_responsavel`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ocorrencia_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `fk_ocorrencia_usuario_registro` FOREIGN KEY (`id_usuario_registro`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_ocorrencia_local` CHECK (`id_unidade` is not null or `id_area` is not null),
  CONSTRAINT `chk_ocorrencia_status` CHECK (`status` in ('ABERTA','EM_ANALISE','EM_TRATAMENTO','RESOLVIDA','ENCERRADA','CANCELADA')),
  CONSTRAINT `chk_ocorrencia_encerramento` CHECK (`data_encerramento` is null or `data_encerramento` >= `data_ocorrencia`)
) ENGINE=InnoDB AUTO_INCREMENT=1501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

