--
-- Table structure for table `orcamento`
--

DROP TABLE IF EXISTS `orcamento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orcamento` (
  `id_orcamento` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `descricao` varchar(255) DEFAULT NULL,
  `periodo_inicio` date NOT NULL,
  `periodo_fim` date NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'EM_ELABORACAO',
  `data_criacao` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_orcamento`),
  KEY `fk_orcamento_condominio` (`id_condominio`),
  CONSTRAINT `fk_orcamento_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `chk_orcamento_periodo` CHECK (`periodo_fim` >= `periodo_inicio`),
  CONSTRAINT `chk_orcamento_status` CHECK (`status` in ('EM_ELABORACAO','APROVADO','ENCERRADO','CANCELADO'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

