  `id_categoria_financeira` bigint(20) unsigned NOT NULL,
  `id_centro_custo` bigint(20) unsigned DEFAULT NULL,
  `valor_previsto` decimal(14,2) NOT NULL,
  `observacao` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_orcamento_item`),
