DROP TABLE IF EXISTS `ordem_manutencao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ordem_manutencao` (
  `id_ordem_manutencao` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_plano_manutencao` bigint(20) unsigned DEFAULT NULL,
  `id_solicitacao` bigint(20) unsigned DEFAULT NULL,
  `id_equipamento` bigint(20) unsigned DEFAULT NULL,
  `id_area` bigint(20) unsigned DEFAULT NULL,
  `id_funcionario_responsavel` bigint(20) unsigned DEFAULT NULL,
  `id_fornecedor` bigint(20) unsigned DEFAULT NULL,
  `tipo` varchar(20) NOT NULL,
  `prioridade` varchar(20) NOT NULL DEFAULT 'NORMAL',
  `descricao` varchar(1000) DEFAULT NULL,
  `data_abertura` datetime NOT NULL DEFAULT current_timestamp(),
  `data_prevista_inicio` datetime DEFAULT NULL,
  `data_prevista_fim` datetime DEFAULT NULL,
  `data_inicio_real` datetime DEFAULT NULL,
  `data_conclusao` datetime DEFAULT NULL,
  `custo_previsto` decimal(14,2) NOT NULL DEFAULT 0.00,
  `status` varchar(30) NOT NULL DEFAULT 'ABERTA',
  PRIMARY KEY (`id_ordem_manutencao`),
  KEY `fk_om_plano` (`id_plano_manutencao`),
  KEY `fk_om_solicitacao` (`id_solicitacao`),
  KEY `fk_om_area` (`id_area`),
  KEY `fk_om_funcionario` (`id_funcionario_responsavel`),
  KEY `fk_om_fornecedor` (`id_fornecedor`),
  KEY `idx_ordem_manutencao_status` (`id_condominio`,`status`,`data_abertura`),
  KEY `idx_ordem_equipamento` (`id_equipamento`,`status`),
  CONSTRAINT `fk_om_area` FOREIGN KEY (`id_area`) REFERENCES `area_comum` (`id_area`) ON UPDATE CASCADE,
  CONSTRAINT `fk_om_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_om_equipamento` FOREIGN KEY (`id_equipamento`) REFERENCES `equipamento` (`id_equipamento`) ON UPDATE CASCADE,
  CONSTRAINT `fk_om_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_om_funcionario` FOREIGN KEY (`id_funcionario_responsavel`) REFERENCES `funcionario_condominio` (`id_vinculo_funcionario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_om_plano` FOREIGN KEY (`id_plano_manutencao`) REFERENCES `plano_manutencao` (`id_plano_manutencao`) ON UPDATE CASCADE,
  CONSTRAINT `fk_om_solicitacao` FOREIGN KEY (`id_solicitacao`) REFERENCES `solicitacao_manutencao` (`id_solicitacao`) ON UPDATE CASCADE,
  CONSTRAINT `chk_om_alvo` CHECK (`id_equipamento` is not null or `id_area` is not null),
  CONSTRAINT `chk_om_tipo` CHECK (`tipo` in ('PREVENTIVA','CORRETIVA','PREDITIVA','INSPECAO')),
  CONSTRAINT `chk_om_prioridade` CHECK (`prioridade` in ('BAIXA','NORMAL','ALTA','URGENTE')),
  CONSTRAINT `chk_om_custo` CHECK (`custo_previsto` >= 0),
  CONSTRAINT `chk_om_status` CHECK (`status` in ('ABERTA','PROGRAMADA','EM_EXECUCAO','PAUSADA','CONCLUIDA','CANCELADA')),
  CONSTRAINT `chk_om_datas_previstas` CHECK (`data_prevista_fim` is null or `data_prevista_inicio` is null or `data_prevista_fim` >= `data_prevista_inicio`),
  CONSTRAINT `chk_om_data_conclusao` CHECK (`data_conclusao` is null or `data_conclusao` >= `data_abertura`)
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

