/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_ordem_manutencao_au

AFTER UPDATE
ON ordem_manutencao

FOR EACH ROW

BEGIN

    IF
        OLD.status <> 'CONCLUIDA'

        AND NEW.status = 'CONCLUIDA'

        AND NEW.id_plano_manutencao
            IS NOT NULL

        AND NEW.data_conclusao
            IS NOT NULL

    THEN


        UPDATE plano_manutencao

        SET

            data_ultima_execucao =
            DATE(
                NEW.data_conclusao
            ),

            proxima_execucao =
            DATE_ADD(

                DATE(
                    NEW.data_conclusao
                ),

                INTERVAL
                periodicidade_dias
                DAY
            )

        WHERE
            id_plano_manutencao =
            NEW.id_plano_manutencao;


    END IF;

END */;;
DELIMITER ;
