DROP TABLE IF EXISTS `ordem_manutencao_custo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ordem_manutencao_custo` (
  `id_custo` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_ordem_manutencao` bigint(20) unsigned NOT NULL,
  `id_fornecedor` bigint(20) unsigned DEFAULT NULL,
  `tipo_custo` varchar(20) NOT NULL,
  `descricao` varchar(255) NOT NULL,
  `quantidade` decimal(12,3) NOT NULL DEFAULT 1.000,
  `valor_unitario` decimal(14,2) NOT NULL,
  `valor_total` decimal(14,2) GENERATED ALWAYS AS (`quantidade` * `valor_unitario`) STORED,
  `data_registro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_custo`),
  KEY `fk_omc_fornecedor` (`id_fornecedor`),
  KEY `idx_ordem_custo` (`id_ordem_manutencao`,`tipo_custo`),
  CONSTRAINT `fk_omc_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_omc_ordem` FOREIGN KEY (`id_ordem_manutencao`) REFERENCES `ordem_manutencao` (`id_ordem_manutencao`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_omc_tipo` CHECK (`tipo_custo` in ('MATERIAL','MAO_OBRA','SERVICO','DESLOCAMENTO','OUTRO')),
  CONSTRAINT `chk_omc_quantidade` CHECK (`quantidade` > 0),
  CONSTRAINT `chk_omc_valor` CHECK (`valor_unitario` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
