  `meio_pagamento` varchar(20) NOT NULL,
  `identificador_externo` varchar(150) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'CONFIRMADO',
  `data_registro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_pagamento`),
  KEY `fk_pagamento_transacao` (`id_transacao`),
  KEY `idx_pagamento_cobranca_data` (`id_cobranca`,`data_pagamento`),
