  CONSTRAINT `fk_pagamento_transacao` FOREIGN KEY (`id_transacao`) REFERENCES `transacao_cobranca` (`id_transacao`) ON UPDATE CASCADE,
  CONSTRAINT `chk_pagamento_valor` CHECK (`valor` > 0),
  CONSTRAINT `chk_pagamento_meio` CHECK (`meio_pagamento` in ('PIX','BOLETO','CARTAO','TRANSFERENCIA','DINHEIRO','OUTRO')),
  CONSTRAINT `chk_pagamento_status` CHECK (`status` in ('PENDENTE','CONFIRMADO','PARCIALMENTE_ESTORNADO','ESTORNADO','CANCELADO'))
) ENGINE=InnoDB AUTO_INCREMENT=3006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
