--
-- Table structure for table `pessoa_unidade`
--

DROP TABLE IF EXISTS `pessoa_unidade`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pessoa_unidade` (
  `id_vinculo` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_pessoa` bigint(20) unsigned NOT NULL,
  `id_unidade` bigint(20) unsigned NOT NULL,
  `id_responsavel` bigint(20) unsigned DEFAULT NULL,
  `tipo_vinculo` varchar(30) NOT NULL,
  `data_inicio` date NOT NULL,
  `data_fim` date DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_vinculo`),
  KEY `fk_pu_pessoa` (`id_pessoa`),
  KEY `fk_pu_responsavel` (`id_responsavel`),
  KEY `idx_pessoa_unidade_unidade_ativo` (`id_unidade`,`ativo`),
  CONSTRAINT `fk_pu_pessoa` FOREIGN KEY (`id_pessoa`) REFERENCES `pessoa` (`id_pessoa`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pu_responsavel` FOREIGN KEY (`id_responsavel`) REFERENCES `pessoa` (`id_pessoa`) ON UPDATE CASCADE,
  CONSTRAINT `fk_pu_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `chk_pu_tipo_vinculo` CHECK (`tipo_vinculo` in ('PROPRIETARIO','INQUILINO','MORADOR','DEPENDENTE','RESPONSAVEL')),
  CONSTRAINT `chk_pu_datas` CHECK (`data_fim` is null or `data_fim` >= `data_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=9192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

