DROP TABLE IF EXISTS `pet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pet` (
  `id_pet` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_unidade` bigint(20) unsigned NOT NULL,
  `nome` varchar(60) NOT NULL,
  `especie` varchar(40) NOT NULL,
  `raca` varchar(60) DEFAULT NULL,
  `observacao` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVO',
  PRIMARY KEY (`id_pet`),
  KEY `fk_pet_unidade` (`id_unidade`),
  CONSTRAINT `fk_pet_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `chk_pet_status` CHECK (`status` in ('ATIVO','INATIVO'))
) ENGINE=InnoDB AUTO_INCREMENT=1201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
