--
-- Table structure for table `plano_conta`
--

DROP TABLE IF EXISTS `plano_conta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `plano_conta` (
  `id_plano_conta` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_conta_pai` bigint(20) unsigned DEFAULT NULL,
  `codigo` varchar(30) NOT NULL,
  `nome` varchar(100) NOT NULL,
  `natureza` varchar(10) NOT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_plano_conta`),
  UNIQUE KEY `uq_plano_conta_codigo` (`id_condominio`,`codigo`),
  KEY `fk_plano_conta_pai` (`id_conta_pai`),
  CONSTRAINT `fk_plano_conta_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_plano_conta_pai` FOREIGN KEY (`id_conta_pai`) REFERENCES `plano_conta` (`id_plano_conta`) ON UPDATE CASCADE,
  CONSTRAINT `chk_plano_conta_natureza` CHECK (`natureza` in ('RECEITA','DESPESA'))
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
