--
-- Table structure for table `plano_manutencao`
--

DROP TABLE IF EXISTS `plano_manutencao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `plano_manutencao` (
  `id_plano_manutencao` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_equipamento` bigint(20) unsigned NOT NULL,
  `id_funcionario_responsavel` bigint(20) unsigned DEFAULT NULL,
  `id_fornecedor_preferencial` bigint(20) unsigned DEFAULT NULL,
  `nome` varchar(150) NOT NULL,
  `descricao` varchar(500) DEFAULT NULL,
  `periodicidade_dias` int(10) unsigned NOT NULL,
  `data_ultima_execucao` date DEFAULT NULL,
  `proxima_execucao` date NOT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_plano_manutencao`),
  KEY `fk_plano_equipamento` (`id_equipamento`),
  KEY `fk_plano_funcionario` (`id_funcionario_responsavel`),
  KEY `fk_plano_fornecedor` (`id_fornecedor_preferencial`),
  KEY `idx_plano_proxima_execucao` (`ativo`,`proxima_execucao`),
  CONSTRAINT `fk_plano_equipamento` FOREIGN KEY (`id_equipamento`) REFERENCES `equipamento` (`id_equipamento`) ON UPDATE CASCADE,
  CONSTRAINT `fk_plano_fornecedor` FOREIGN KEY (`id_fornecedor_preferencial`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `fk_plano_funcionario` FOREIGN KEY (`id_funcionario_responsavel`) REFERENCES `funcionario_condominio` (`id_vinculo_funcionario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_plano_periodicidade` CHECK (`periodicidade_dias` > 0),
  CONSTRAINT `chk_plano_datas` CHECK (`data_ultima_execucao` is null or `proxima_execucao` >= `data_ultima_execucao`)
) ENGINE=InnoDB AUTO_INCREMENT=601 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

