--
-- Table structure for table `regra_encargo`
--

DROP TABLE IF EXISTS `regra_encargo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `regra_encargo` (
  `id_regra_encargo` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `tipo_encargo` varchar(20) NOT NULL,
  `percentual` decimal(8,4) DEFAULT NULL,
  `valor_fixo` decimal(14,2) DEFAULT NULL,
  `dias_carencia` int(10) unsigned NOT NULL DEFAULT 0,
  `vigencia_inicio` date NOT NULL,
  `vigencia_fim` date DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_regra_encargo`),
  KEY `fk_regra_encargo_condominio` (`id_condominio`),
  CONSTRAINT `fk_regra_encargo_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `chk_regra_encargo_tipo` CHECK (`tipo_encargo` in ('MULTA','JUROS','ENCARGO')),
  CONSTRAINT `chk_regra_encargo_valores` CHECK (`percentual` is not null or `valor_fixo` is not null),
