DROP TABLE IF EXISTS `reserva`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reserva` (
  `id_reserva` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_area` bigint(20) unsigned NOT NULL,
  `id_regra_reserva` bigint(20) unsigned DEFAULT NULL,
  `id_unidade` bigint(20) unsigned NOT NULL,
  `id_solicitante` bigint(20) unsigned NOT NULL,
  `inicio_reserva` datetime NOT NULL,
  `fim_reserva` datetime NOT NULL,
  `quantidade_pessoas` int(10) unsigned DEFAULT NULL,
  `valor_taxa` decimal(12,2) NOT NULL DEFAULT 0.00,
  `status` varchar(20) NOT NULL DEFAULT 'PENDENTE',
  `data_criacao` datetime NOT NULL DEFAULT current_timestamp(),
  `data_atualizacao` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_reserva`),
  KEY `fk_reserva_regra` (`id_regra_reserva`),
  KEY `fk_reserva_solicitante` (`id_solicitante`),
  KEY `idx_reserva_area_periodo` (`id_area`,`inicio_reserva`,`fim_reserva`,`status`),
  KEY `idx_reserva_unidade_data` (`id_unidade`,`inicio_reserva`),
  CONSTRAINT `fk_reserva_area` FOREIGN KEY (`id_area`) REFERENCES `area_comum` (`id_area`) ON UPDATE CASCADE,
  CONSTRAINT `fk_reserva_regra` FOREIGN KEY (`id_regra_reserva`) REFERENCES `regra_reserva` (`id_regra_reserva`) ON UPDATE CASCADE,
  CONSTRAINT `fk_reserva_solicitante` FOREIGN KEY (`id_solicitante`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `fk_reserva_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `chk_reserva_periodo` CHECK (`fim_reserva` > `inicio_reserva`),
  CONSTRAINT `chk_reserva_quantidade` CHECK (`quantidade_pessoas` is null or `quantidade_pessoas` > 0),
  CONSTRAINT `chk_reserva_valor` CHECK (`valor_taxa` >= 0),
  CONSTRAINT `chk_reserva_status` CHECK (`status` in ('PENDENTE','CONFIRMADA','CANCELADA','CONCLUIDA'))
) ENGINE=InnoDB AUTO_INCREMENT=1476 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
