/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_reserva_bu_conflito

BEFORE UPDATE
ON reserva

FOR EACH ROW

BEGIN

    DECLARE v_conflitos INT DEFAULT 0;


    IF NEW.status IN (
        'PENDENTE',
        'CONFIRMADA'
    ) THEN


        SELECT COUNT(*)

        INTO v_conflitos

        FROM reserva

        WHERE
            id_area =
            NEW.id_area

            AND id_reserva <>
                NEW.id_reserva

            AND status IN (
                'PENDENTE',
                'CONFIRMADA'
            )

            AND NEW.inicio_reserva
                < fim_reserva

            AND NEW.fim_reserva
                > inicio_reserva;


        IF v_conflitos > 0 THEN

            SIGNAL SQLSTATE '45000'

            SET MESSAGE_TEXT =
            'A reprogramação gera conflito com outra reserva.';

        END IF;


    END IF;

END */;;
DELIMITER ;
