/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_reserva_au_historico

AFTER UPDATE
ON reserva

FOR EACH ROW

BEGIN

    DECLARE v_tipo VARCHAR(30);


    IF
        NOT (OLD.status <=> NEW.status)

        OR

        NOT (
            OLD.inicio_reserva
            <=>
            NEW.inicio_reserva
        )

        OR

        NOT (
            OLD.fim_reserva
            <=>
            NEW.fim_reserva
        )

    THEN


        IF
            NEW.status = 'CANCELADA'
            AND OLD.status <> 'CANCELADA'

        THEN

            SET v_tipo =
                'CANCELAMENTO';


        ELSEIF

            NOT (
                OLD.inicio_reserva
                <=>
                NEW.inicio_reserva
            )

            OR

            NOT (
                OLD.fim_reserva
                <=>
                NEW.fim_reserva
            )

        THEN

            SET v_tipo =
                'REPROGRAMACAO';


        ELSE

            SET v_tipo =
                'ALTERACAO_STATUS';

        END IF;


        INSERT INTO reserva_historico
        (
            id_reserva,
            tipo_evento,

            status_anterior,
            status_novo,

            inicio_anterior,
            fim_anterior,

            inicio_novo,
            fim_novo,

            observacao
        )

        VALUES
        (
            NEW.id_reserva,
            v_tipo,

            OLD.status,
            NEW.status,

            OLD.inicio_reserva,
            OLD.fim_reserva,

            NEW.inicio_reserva,
            NEW.fim_reserva,

            'Alteração registrada automaticamente'
        );


    END IF;

END */;;
DELIMITER ;
