--
-- Table structure for table `solicitacao_manutencao`
--

DROP TABLE IF EXISTS `solicitacao_manutencao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `solicitacao_manutencao` (
  `id_solicitacao` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `id_chamado` bigint(20) unsigned DEFAULT NULL,
  `id_equipamento` bigint(20) unsigned DEFAULT NULL,
  `id_area` bigint(20) unsigned DEFAULT NULL,
  `id_solicitante` bigint(20) unsigned NOT NULL,
  `titulo` varchar(200) NOT NULL,
  `descricao` varchar(1000) DEFAULT NULL,
  `prioridade` varchar(20) NOT NULL DEFAULT 'NORMAL',
  `status` varchar(30) NOT NULL DEFAULT 'ABERTA',
  `data_abertura` datetime NOT NULL DEFAULT current_timestamp(),
  `data_encerramento` datetime DEFAULT NULL,
  PRIMARY KEY (`id_solicitacao`),
  KEY `fk_sm_condominio` (`id_condominio`),
  KEY `fk_sm_chamado` (`id_chamado`),
  KEY `fk_sm_equipamento` (`id_equipamento`),
  KEY `fk_sm_area` (`id_area`),
  KEY `fk_sm_solicitante` (`id_solicitante`),
  CONSTRAINT `fk_sm_area` FOREIGN KEY (`id_area`) REFERENCES `area_comum` (`id_area`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sm_chamado` FOREIGN KEY (`id_chamado`) REFERENCES `chamado` (`id_chamado`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sm_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sm_equipamento` FOREIGN KEY (`id_equipamento`) REFERENCES `equipamento` (`id_equipamento`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sm_solicitante` FOREIGN KEY (`id_solicitante`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_sm_alvo` CHECK (`id_equipamento` is not null or `id_area` is not null),
  CONSTRAINT `chk_sm_prioridade` CHECK (`prioridade` in ('BAIXA','NORMAL','ALTA','URGENTE')),
  CONSTRAINT `chk_sm_status` CHECK (`status` in ('ABERTA','EM_ANALISE','APROVADA','EM_EXECUCAO','CONCLUIDA','CANCELADA')),
  CONSTRAINT `chk_sm_datas` CHECK (`data_encerramento` is null or `data_encerramento` >= `data_abertura`)
) ENGINE=InnoDB AUTO_INCREMENT=1501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

