DROP TABLE IF EXISTS `token_recuperacao_senha`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `token_recuperacao_senha` (
  `id_token` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_usuario` bigint(20) unsigned NOT NULL,
  `token_hash` varchar(255) NOT NULL,
  `data_criacao` datetime NOT NULL DEFAULT current_timestamp(),
  `data_expiracao` datetime NOT NULL,
  `data_utilizacao` datetime DEFAULT NULL,
  `utilizado` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id_token`),
  UNIQUE KEY `uq_token_recuperacao_hash` (`token_hash`),
  KEY `fk_token_usuario` (`id_usuario`),
  CONSTRAINT `fk_token_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_token_expiracao` CHECK (`data_expiracao` > `data_criacao`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
