  `id_cobranca` bigint(20) unsigned NOT NULL,
  `meio_pagamento` varchar(20) NOT NULL,
  `identificador_externo` varchar(150) DEFAULT NULL,
  `status` varchar(30) NOT NULL,
  `data_criacao` datetime NOT NULL DEFAULT current_timestamp(),
  `data_expiracao` datetime DEFAULT NULL,
  PRIMARY KEY (`id_transacao`),
  UNIQUE KEY `uq_transacao_identificador` (`identificador_externo`),
  KEY `fk_transacao_cobranca` (`id_cobranca`),
  CONSTRAINT `fk_transacao_cobranca` FOREIGN KEY (`id_cobranca`) REFERENCES `cobranca` (`id_cobranca`) ON UPDATE CASCADE,
  CONSTRAINT `chk_transacao_meio` CHECK (`meio_pagamento` in ('PIX','BOLETO','CARTAO','TRANSFERENCIA','OUTRO')),
  CONSTRAINT `chk_transacao_status` CHECK (`status` in ('CRIADA','PENDENTE','PAGA','EXPIRADA','CANCELADA','ERRO'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
