  `fracao_ideal` decimal(10,6) DEFAULT NULL,
  PRIMARY KEY (`id_unidade`),
  KEY `idx_unidade_condominio_identificacao` (`id_condominio`,`identificacao`),
  CONSTRAINT `fk_unidade_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `chk_unidade_fracao` CHECK (`fracao_ideal` is null or `fracao_ideal` >= 0),
  CONSTRAINT `chk_unidade_situacao` CHECK (`situacao` in ('ATIVA','INATIVA','DESOCUPADA'))
) ENGINE=InnoDB AUTO_INCREMENT=2026 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
