DROP TABLE IF EXISTS `usuario`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuario` (
  `id_usuario` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_pessoa` bigint(20) unsigned NOT NULL,
  `email_login` varchar(150) NOT NULL,
  `senha_hash` varchar(255) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVO',
  `ultimo_login` datetime DEFAULT NULL,
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_usuario`),
  UNIQUE KEY `uq_usuario_pessoa` (`id_pessoa`),
  UNIQUE KEY `uq_usuario_email` (`email_login`),
  KEY `idx_usuario_status` (`status`),
  CONSTRAINT `fk_usuario_pessoa` FOREIGN KEY (`id_pessoa`) REFERENCES `pessoa` (`id_pessoa`) ON UPDATE CASCADE,
  CONSTRAINT `chk_usuario_status` CHECK (`status` in ('ATIVO','INATIVO','BLOQUEADO'))
) ENGINE=InnoDB AUTO_INCREMENT=5001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
