--
-- Table structure for table `usuario_perfil_condominio`
--

DROP TABLE IF EXISTS `usuario_perfil_condominio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuario_perfil_condominio` (
  `id_usuario_perfil` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_usuario` bigint(20) unsigned NOT NULL,
  `id_perfil` bigint(20) unsigned NOT NULL,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `data_inicio` date NOT NULL,
  `data_fim` date DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_usuario_perfil`),
  UNIQUE KEY `uq_usuario_perfil_condominio` (`id_usuario`,`id_perfil`,`id_condominio`,`data_inicio`),
  KEY `fk_upc_perfil` (`id_perfil`),
  KEY `fk_upc_condominio` (`id_condominio`),
  CONSTRAINT `fk_upc_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `fk_upc_perfil` FOREIGN KEY (`id_perfil`) REFERENCES `perfil` (`id_perfil`) ON UPDATE CASCADE,
  CONSTRAINT `fk_upc_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`) ON UPDATE CASCADE,
  CONSTRAINT `chk_upc_datas` CHECK (`data_fim` is null or `data_fim` >= `data_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=5001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

