DROP TABLE IF EXISTS `vaga`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vaga` (
  `id_vaga` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_condominio` bigint(20) unsigned NOT NULL,
  `identificacao` varchar(30) NOT NULL,
  `tipo` varchar(30) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVA',
  PRIMARY KEY (`id_vaga`),
  UNIQUE KEY `uq_vaga_condominio_identificacao` (`id_condominio`,`identificacao`),
  CONSTRAINT `fk_vaga_condominio` FOREIGN KEY (`id_condominio`) REFERENCES `condominio` (`id_condominio`) ON UPDATE CASCADE,
  CONSTRAINT `chk_vaga_status` CHECK (`status` in ('ATIVA','INATIVA','MANUTENCAO'))
) ENGINE=InnoDB AUTO_INCREMENT=1501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
