--
-- Table structure for table `vaga_unidade`
--

DROP TABLE IF EXISTS `vaga_unidade`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vaga_unidade` (
  `id_vaga_unidade` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_vaga` bigint(20) unsigned NOT NULL,
  `id_unidade` bigint(20) unsigned NOT NULL,
  `data_inicio` date NOT NULL,
  `data_fim` date DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_vaga_unidade`),
  KEY `fk_vaga_unidade_unidade` (`id_unidade`),
  KEY `idx_vaga_unidade_vaga_ativo` (`id_vaga`,`ativo`),
  CONSTRAINT `fk_vaga_unidade_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `fk_vaga_unidade_vaga` FOREIGN KEY (`id_vaga`) REFERENCES `vaga` (`id_vaga`) ON UPDATE CASCADE,
  CONSTRAINT `chk_vaga_unidade_datas` CHECK (`data_fim` is null or `data_fim` >= `data_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=1328 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

