--
-- Table structure for table `veiculo`
--

DROP TABLE IF EXISTS `veiculo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `veiculo` (
  `id_veiculo` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_pessoa` bigint(20) unsigned DEFAULT NULL,
  `id_unidade` bigint(20) unsigned DEFAULT NULL,
  `id_vaga` bigint(20) unsigned DEFAULT NULL,
  `placa` varchar(10) NOT NULL,
  `marca` varchar(50) DEFAULT NULL,
  `modelo` varchar(60) DEFAULT NULL,
  `cor` varchar(30) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVO',
  PRIMARY KEY (`id_veiculo`),
  UNIQUE KEY `uq_veiculo_placa` (`placa`),
  KEY `fk_veiculo_pessoa` (`id_pessoa`),
  KEY `fk_veiculo_unidade` (`id_unidade`),
  KEY `fk_veiculo_vaga` (`id_vaga`),
  CONSTRAINT `fk_veiculo_pessoa` FOREIGN KEY (`id_pessoa`) REFERENCES `pessoa` (`id_pessoa`) ON UPDATE CASCADE,
  CONSTRAINT `fk_veiculo_unidade` FOREIGN KEY (`id_unidade`) REFERENCES `unidade` (`id_unidade`) ON UPDATE CASCADE,
  CONSTRAINT `fk_veiculo_vaga` FOREIGN KEY (`id_vaga`) REFERENCES `vaga` (`id_vaga`) ON UPDATE CASCADE,
  CONSTRAINT `chk_veiculo_vinculo` CHECK (`id_pessoa` is not null or `id_unidade` is not null),
  CONSTRAINT `chk_veiculo_status` CHECK (`status` in ('ATIVO','INATIVO'))
) ENGINE=InnoDB AUTO_INCREMENT=2389 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

