DROP TABLE IF EXISTS `visitante`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `visitante` (
  `id_visitante` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_fornecedor` bigint(20) unsigned DEFAULT NULL,
  `tipo_visitante` varchar(20) NOT NULL DEFAULT 'VISITANTE',
  `nome` varchar(150) NOT NULL,
  `documento` varchar(30) DEFAULT NULL,
  `telefone` varchar(20) DEFAULT NULL,
  `placa_veiculo` varchar(10) DEFAULT NULL,
  `observacao` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ATIVO',
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_visitante`),
  UNIQUE KEY `uq_visitante_documento` (`documento`),
  KEY `fk_visitante_fornecedor` (`id_fornecedor`),
  KEY `idx_visitante_nome` (`nome`),
  CONSTRAINT `fk_visitante_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedor` (`id_fornecedor`) ON UPDATE CASCADE,
  CONSTRAINT `chk_visitante_tipo` CHECK (`tipo_visitante` in ('VISITANTE','PRESTADOR')),
  CONSTRAINT `chk_visitante_status` CHECK (`status` in ('ATIVO','INATIVO','BLOQUEADO'))
) ENGINE=InnoDB AUTO_INCREMENT=4001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

