--
-- Dumping routines for database 'sgiec'
--
/*!50003 DROP PROCEDURE IF EXISTS `sp_criar_reserva` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_criar_reserva`(

    IN p_id_area          BIGINT UNSIGNED,

    IN p_id_regra_reserva BIGINT UNSIGNED,

    IN p_id_unidade       BIGINT UNSIGNED,

    IN p_id_solicitante   BIGINT UNSIGNED,

    IN p_inicio           DATETIME,

    IN p_fim              DATETIME,

    IN p_quantidade       INT UNSIGNED

)
BEGIN

    DECLARE v_existe INT DEFAULT 0;

    DECLARE v_reservavel BOOLEAN;

    DECLARE v_status_area VARCHAR(20);

    DECLARE v_capacidade INT;

    DECLARE v_taxa DECIMAL(12,2);

    DECLARE v_inicio_regra TIME;

    DECLARE v_fim_regra TIME;

    DECLARE v_duracao_min INT;

    DECLARE v_duracao_max INT;

    DECLARE v_antecedencia_min INT;

    DECLARE v_antecedencia_max INT;

    DECLARE v_limite_pessoas INT;


    -- ========================================================
    -- Verifica se a área existe
    -- ========================================================

    SELECT COUNT(*)
    INTO v_existe
    FROM area_comum
    WHERE id_area = p_id_area;


    IF v_existe = 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Área comum não encontrada.';

    END IF;


    SELECT
        reservavel,
        status,
        capacidade

    INTO
        v_reservavel,
        v_status_area,
        v_capacidade

    FROM area_comum

    WHERE id_area = p_id_area;


    IF v_reservavel = FALSE THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Esta área não permite reservas.';

    END IF;


    IF v_status_area <> 'DISPONIVEL' THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Área comum indisponível.';

    END IF;


    -- ========================================================
    -- Verifica se unidade e área pertencem ao mesmo condomínio
    -- ========================================================

    SELECT COUNT(*)

    INTO v_existe

    FROM unidade u

    INNER JOIN area_comum a
        ON a.id_condominio =
           u.id_condominio

    WHERE
        u.id_unidade = p_id_unidade
        AND a.id_area = p_id_area;


    IF v_existe = 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'A unidade e a área pertencem a condomínios diferentes.';

    END IF;


    -- ========================================================
    -- Regra da reserva
    -- ========================================================

    SELECT COUNT(*)

    INTO v_existe

    FROM regra_reserva

    WHERE
        id_regra_reserva =
        p_id_regra_reserva

        AND id_area =
        p_id_area

        AND ativo = TRUE

        AND vigencia_inicio <= DATE(p_inicio)

        AND (
            vigencia_fim IS NULL
            OR vigencia_fim >= DATE(p_inicio)
        );


    IF v_existe = 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Regra de reserva inválida ou fora da vigência.';

    END IF;


    SELECT
        horario_inicio,
        horario_fim,
        duracao_minima_minutos,
        duracao_maxima_minutos,
        antecedencia_minima_horas,
        antecedencia_maxima_dias,
        limite_pessoas,
        taxa_uso

    INTO
        v_inicio_regra,
        v_fim_regra,
        v_duracao_min,
        v_duracao_max,
        v_antecedencia_min,
        v_antecedencia_max,
        v_limite_pessoas,
        v_taxa

    FROM regra_reserva

    WHERE id_regra_reserva =
          p_id_regra_reserva;


    -- ========================================================
    -- Validação das datas
    -- ========================================================

    IF p_fim <= p_inicio THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'O horário final deve ser posterior ao horário inicial.';

    END IF;


    IF p_inicio <= NOW() THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'A reserva deve ser realizada para uma data futura.';

    END IF;


    -- ========================================================
    -- Horário permitido
    -- ========================================================

    IF
        TIME(p_inicio) < v_inicio_regra
        OR
        TIME(p_fim) > v_fim_regra
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Reserva fora do horário permitido.';

    END IF;


    -- ========================================================
    -- Duração
    -- ========================================================

    IF
        TIMESTAMPDIFF(
            MINUTE,
            p_inicio,
            p_fim
        ) < v_duracao_min
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Duração inferior ao mínimo permitido.';

    END IF;


    IF
        TIMESTAMPDIFF(
            MINUTE,
            p_inicio,
            p_fim
        ) > v_duracao_max
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Duração superior ao máximo permitido.';

    END IF;


    -- ========================================================
    -- Antecedência mínima
    -- ========================================================

    IF
        TIMESTAMPDIFF(
            HOUR,
            NOW(),
            p_inicio
        ) < v_antecedencia_min
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Reserva realizada com antecedência menor que a permitida.';

    END IF;


    -- ========================================================
    -- Antecedência máxima
    -- ========================================================

    IF
        v_antecedencia_max IS NOT NULL
        AND DATE(p_inicio) >
            DATE_ADD(
                CURRENT_DATE,
                INTERVAL v_antecedencia_max DAY
            )
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Reserva realizada com antecedência maior que a permitida.';

    END IF;


    -- ========================================================
    -- Capacidade
    -- ========================================================

    IF
        p_quantidade IS NOT NULL
        AND v_capacidade IS NOT NULL
        AND p_quantidade > v_capacidade
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Quantidade superior à capacidade da área.';

    END IF;


    IF
        p_quantidade IS NOT NULL
        AND v_limite_pessoas IS NOT NULL
        AND p_quantidade > v_limite_pessoas
    THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Quantidade superior ao limite definido na regra.';

    END IF;


    -- ========================================================
    -- Verificação de conflito
    --
    -- nova_inicio < fim_existente
    -- E
    -- nova_fim > inicio_existente
    -- ========================================================

    SELECT COUNT(*)

    INTO v_existe

    FROM reserva

    WHERE
        id_area = p_id_area

        AND status IN (
            'PENDENTE',
            'CONFIRMADA'
        )

        AND p_inicio < fim_reserva

        AND p_fim > inicio_reserva;


    IF v_existe > 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Já existe uma reserva conflitante para esta área.';

    END IF;


    -- ========================================================
    -- Criação
    -- ========================================================

    INSERT INTO reserva
    (
        id_area,
        id_regra_reserva,
        id_unidade,
        id_solicitante,
        inicio_reserva,
        fim_reserva,
        quantidade_pessoas,
        valor_taxa,
        status
    )

    VALUES
    (
        p_id_area,
        p_id_regra_reserva,
        p_id_unidade,
        p_id_solicitante,
        p_inicio,
        p_fim,
        p_quantidade,
        v_taxa,
        'PENDENTE'
    );


    SELECT
        LAST_INSERT_ID()
        AS id_reserva_criada;

END ;;
DELIMITER ;
