/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_pagamento`(

    IN p_id_cobranca BIGINT UNSIGNED,

    IN p_valor DECIMAL(14,2),

    IN p_meio_pagamento VARCHAR(20),

    IN p_id_transacao BIGINT UNSIGNED,

    IN p_identificador_externo VARCHAR(150)

)
BEGIN

    DECLARE v_existe INT DEFAULT 0;

    DECLARE v_id_conta_receber
            BIGINT UNSIGNED;

    DECLARE v_valor_original
            DECIMAL(14,2);

    DECLARE v_encargos
            DECIMAL(14,2)
            DEFAULT 0;

    DECLARE v_total_pago
            DECIMAL(14,2)
            DEFAULT 0;

    DECLARE v_total_devido
            DECIMAL(14,2)
            DEFAULT 0;


    DECLARE EXIT HANDLER FOR SQLEXCEPTION

    BEGIN

        ROLLBACK;

        RESIGNAL;

    END;


    START TRANSACTION;


    -- ========================================================
    -- Verifica cobrança
    -- ========================================================

    SELECT COUNT(*)

    INTO v_existe

    FROM cobranca

    WHERE id_cobranca =
          p_id_cobranca;


    IF v_existe = 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'Cobrança não encontrada.';

    END IF;


    -- ========================================================
    -- Obtém conta a receber
    -- ========================================================

    SELECT
        cr.id_conta_receber,
        cr.valor

    INTO
        v_id_conta_receber,
        v_valor_original

    FROM cobranca cb

    INNER JOIN conta_receber cr
        ON cr.id_conta_receber =
           cb.id_conta_receber

    WHERE cb.id_cobranca =
          p_id_cobranca

    FOR UPDATE;


    -- ========================================================
    -- Verifica valor
    -- ========================================================

    IF p_valor <= 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'O valor do pagamento deve ser maior que zero.';

    END IF;


    -- ========================================================
    -- Verifica transação, caso informada
    -- ========================================================

    IF p_id_transacao IS NOT NULL THEN

        SELECT COUNT(*)

        INTO v_existe

        FROM transacao_cobranca

        WHERE
            id_transacao =
            p_id_transacao

            AND id_cobranca =
            p_id_cobranca;


        IF v_existe = 0 THEN

            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
            'A transação não pertence a esta cobrança.';

        END IF;

    END IF;


    -- ========================================================
    -- Registra pagamento
    -- ========================================================

    INSERT INTO pagamento
    (
        id_cobranca,
        id_transacao,
        data_pagamento,
        valor,
        meio_pagamento,
        identificador_externo,
        status
    )

    VALUES
    (
        p_id_cobranca,
        p_id_transacao,
        NOW(),
        p_valor,
        p_meio_pagamento,
        p_identificador_externo,
        'CONFIRMADO'
    );


    -- ========================================================
    -- Atualiza transação externa
    -- ========================================================

    IF p_id_transacao IS NOT NULL THEN

        UPDATE transacao_cobranca

        SET status = 'PAGA'

        WHERE id_transacao =
              p_id_transacao;

    END IF;


    -- ========================================================
    -- Soma encargos
    -- ========================================================

    SELECT
        COALESCE(
            SUM(valor),
            0
        )

    INTO v_encargos

    FROM cobranca_encargo

    WHERE id_cobranca =
          p_id_cobranca;


    SET v_total_devido =
        v_valor_original
        + v_encargos;


    -- ========================================================
    -- Soma pagamentos confirmados
    -- ========================================================

    SELECT
        COALESCE(
            SUM(valor),
            0
        )

    INTO v_total_pago

    FROM pagamento

    WHERE
        id_cobranca =
        p_id_cobranca

        AND status IN (
            'CONFIRMADO',
            'PARCIALMENTE_ESTORNADO'
        );


    -- ========================================================
    -- Atualiza situação
    -- ========================================================

    IF v_total_pago >= v_total_devido THEN

        UPDATE conta_receber

        SET status = 'LIQUIDADA'

        WHERE id_conta_receber =
              v_id_conta_receber;


    ELSEIF v_total_pago > 0 THEN

        UPDATE conta_receber

        SET status = 'PARCIAL'

        WHERE id_conta_receber =
              v_id_conta_receber;


    ELSE

        UPDATE conta_receber

        SET status = 'ABERTA'

        WHERE id_conta_receber =
              v_id_conta_receber;

    END IF;


    COMMIT;


    SELECT
        LAST_INSERT_ID()
        AS id_pagamento,

        v_total_devido
        AS total_devido,

        v_total_pago
        AS total_pago,

        v_total_devido -
        v_total_pago
        AS saldo_restante;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_resumo_financeiro` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_resumo_financeiro`(

    IN p_id_condominio BIGINT UNSIGNED,

    IN p_data_inicio DATE,

    IN p_data_fim DATE

)
BEGIN

    IF p_data_fim < p_data_inicio THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
        'A data final não pode ser anterior à data inicial.';

    END IF;


    SELECT

        p_id_condominio
        AS id_condominio,

        p_data_inicio
        AS periodo_inicio,

        p_data_fim
        AS periodo_fim,


        COALESCE(
            SUM(
                CASE

                    WHEN pc.natureza =
                         'RECEITA'

                    THEN lf.valor

                    ELSE 0

                END
            ),
            0
        ) AS total_receitas,


        COALESCE(
            SUM(
                CASE

                    WHEN pc.natureza =
                         'DESPESA'

                    THEN lf.valor

                    ELSE 0

                END
            ),
            0
        ) AS total_despesas,


        COALESCE(
            SUM(
                CASE

                    WHEN pc.natureza =
                         'RECEITA'

                    THEN lf.valor

                    WHEN pc.natureza =
                         'DESPESA'

                    THEN -lf.valor

                    ELSE 0

                END
            ),
            0
        ) AS saldo

    FROM lancamento_financeiro lf

    INNER JOIN categoria_financeira cf
        ON cf.id_categoria_financeira =
           lf.id_categoria_financeira

    INNER JOIN plano_conta pc
        ON pc.id_plano_conta =
           cf.id_plano_conta

    WHERE
        lf.id_condominio =
        p_id_condominio

        AND DATE(
            lf.data_lancamento
        )
        BETWEEN
            p_data_inicio
            AND p_data_fim

        AND lf.status =
            'REALIZADO';

END ;;
DELIMITER ;
